@import url('https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@600;800&family=Figtree:wght@400;600;700;800&display=swap');
.mk{--primary:#1b8168;--on-primary:#fff;--primary-fg:#117b63;--primary-soft:#dcf5ec;--accent:#a9c24f;--accent-soft:#eaf2ce;--accent-fg:#56701f;--cream:#f4f8f0;--stage:#edf1ea;--line:#e2eadf;--line-strong:#cbdac7;--paper:#fff;--ink:#1e2e27;--ink-soft:#5c7069;--teal-soft:#d9ecec;--danger:#b23b3b;--danger-soft:#f6e4e2;
 font-family:Figtree,"Segoe UI",system-ui,sans-serif;color:var(--ink);background:var(--stage);padding:24px;display:flex;gap:24px;flex-wrap:wrap;justify-content:center;align-items:flex-start}
.mk *{box-sizing:border-box}
.phone{width:390px;min-height:760px;background:var(--cream);border:1px solid var(--line-strong);border-radius:28px;overflow:hidden;display:flex;flex-direction:column;position:relative}
.cap{width:390px;font-size:12px;font-weight:700;color:var(--ink-soft);margin:0 0 6px 6px}
.col{display:flex;flex-direction:column}
.body{padding:16px;flex:1}
.top{display:flex;align-items:center;gap:10px;margin-bottom:14px}
.back{font-size:14px;font-weight:700;color:var(--primary-fg);text-decoration:none}
h1{font-family:"Bricolage Grotesque",sans-serif;font-size:26px;font-weight:800;line-height:1.15;margin:0;letter-spacing:-.01em}
h2{font-size:16px;font-weight:700;margin:0}
.serif{font-family:"Bricolage Grotesque",sans-serif;font-weight:800}
p{margin:0}
.lead{font-size:15px;line-height:1.35;color:var(--ink-soft);margin-bottom:14px}
.card{background:var(--paper);border:1px solid var(--line);border-radius:22px;padding:14px;display:flex;flex-direction:column;gap:10px}
.list{display:flex;flex-direction:column;gap:12px;list-style:none;margin:0;padding:0}
.row{display:flex;align-items:center;gap:10px}
.between{justify-content:space-between}
.grow{flex:1;min-width:0}
.meta{font-size:13px;color:var(--ink-soft)}
.pill{display:inline-block;border-radius:999px;padding:2px 10px;font-size:12px;font-weight:800}
.p-gift{background:var(--primary-soft);color:var(--primary-fg)}
.p-swap{background:var(--accent-soft);color:var(--accent-fg)}
.p-new{background:var(--primary);color:#fff}
.p-res{background:var(--cream);color:var(--ink-soft);border:1px solid var(--line-strong)}
.p-mine{background:var(--teal-soft);color:var(--ink)}
.p-warn{background:var(--danger-soft);color:var(--danger)}
.band{border-radius:16px;padding:10px 12px;font-size:14px}
.band-hit{background:var(--primary-soft);color:var(--primary-fg);font-weight:800}
.band-none{background:var(--cream)}
.btn{display:flex;align-items:center;justify-content:center;min-height:48px;border-radius:999px;background:var(--primary);color:#fff;font-size:15px;font-weight:800;border:0;padding:0 20px;text-decoration:none;cursor:pointer}
.btn-ghost{background:var(--paper);color:var(--ink);border:1.5px solid var(--line)}
.btn-danger{background:var(--paper);color:var(--danger);border:1.5px solid var(--danger-soft)}
.btn-sm{min-height:40px;font-size:14px;padding:0 14px}
.btn-off{opacity:.55}
.link{color:var(--primary-fg);font-weight:800;font-size:14px;text-decoration:none}
label,.label{display:block;font-size:14px;font-weight:700;margin-bottom:6px}
.input{height:48px;width:100%;border-radius:16px;border:1.5px solid var(--line);background:var(--paper);padding:0 16px;font:inherit;font-size:16px;color:var(--ink);display:flex;align-items:center}
.input.bad{border-color:var(--danger)}
.area{height:88px;align-items:flex-start;padding-top:12px}
.ph{color:var(--ink-soft)}
.err{color:var(--danger);font-size:13px;font-weight:700;margin-top:6px}
.alert{background:var(--danger-soft);color:var(--danger);border-radius:16px;padding:10px 12px;font-size:14px;font-weight:700}
.hint{font-size:12px;color:var(--ink-soft);margin-top:4px}
.field{margin-bottom:14px}
.chips{display:flex;flex-wrap:wrap;gap:8px}
.chip{min-height:40px;border-radius:999px;border:1.5px solid var(--line);background:var(--paper);padding:0 14px;font-size:14px;font-weight:700;display:flex;align-items:center}
.chip.on{background:var(--primary-soft);border-color:var(--primary);color:var(--primary-fg)}
.disc{display:flex;align-items:center;justify-content:space-between;width:100%;min-height:48px;border-radius:16px;border:1.5px solid var(--line);background:var(--paper);padding:0 16px;font:inherit;font-size:15px;font-weight:800;color:var(--ink);margin-bottom:14px}
.panel{border:1.5px solid var(--line);border-radius:18px;background:var(--paper);padding:14px;margin:-6px 0 14px}
.empty{display:flex;flex-direction:column;align-items:center;gap:10px;text-align:center;border:1.5px dashed var(--line-strong);border-radius:28px;background:var(--paper);padding:28px 20px}
.ico{width:64px;height:64px;border-radius:24px;background:var(--accent-soft);color:var(--accent-fg);display:flex;align-items:center;justify-content:center;font-size:26px}
.nav{display:flex;border-top:1px solid var(--line);background:var(--paper);padding:8px 6px 12px}
.tab{flex:1;text-align:center;font-size:12px;font-weight:700;color:var(--ink-soft)}
.tab i{display:block;width:54px;height:30px;border-radius:999px;margin:0 auto 4px;font-style:normal;line-height:30px}
.tab.on{color:var(--primary-fg);font-weight:800}.tab.on i{background:var(--primary-soft)}
.plus{width:48px;height:48px;border-radius:50%;background:var(--primary);color:#fff;font-size:26px;line-height:44px;margin:-6px auto 0;border:4px solid var(--cream)}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.item{position:relative;background:var(--paper);border:1px solid var(--line);border-radius:16px;padding:10px;display:flex;flex-direction:column}
.thumb{aspect-ratio:1;border-radius:12px;background:var(--cream);display:flex;align-items:center;justify-content:center;color:var(--line-strong);font-size:28px}
.item.dim .thumb{opacity:.6}
.iname{font-size:13px;font-weight:700;margin-top:8px}
.istan{font-size:11px;color:var(--ink-soft);margin:2px 0 8px}
.badge-new{position:absolute;top:16px;left:16px}
.toggle{width:46px;height:28px;border-radius:999px;background:var(--primary);position:relative;flex:none}
.toggle::after{content:"";position:absolute;top:3px;left:21px;width:22px;height:22px;border-radius:50%;background:#fff}
.toggle.off{background:var(--line-strong)}.toggle.off::after{left:3px}
.scrim{position:absolute;inset:0;background:rgb(20 28 24 / .55);display:flex;align-items:flex-end}
.sheet{background:var(--paper);border-radius:24px 24px 0 0;padding:20px;width:100%}
.sheet h3{font-family:"Bricolage Grotesque",sans-serif;font-size:18px;font-weight:600;margin:0}
.x{width:36px;height:36px;border-radius:50%;background:var(--cream);color:var(--ink-soft);display:flex;align-items:center;justify-content:center}
.tile{aspect-ratio:4/5;border-radius:26px;padding:16px;display:flex;flex-direction:column;justify-content:space-between;position:relative}
.tile .ti{width:52px;height:52px;border-radius:18px;background:var(--paper);display:flex;align-items:center;justify-content:center;font-size:22px}
.tile b{display:block;font-family:"Bricolage Grotesque",sans-serif;font-size:21px;font-weight:800;line-height:1.15}
.tile small{display:block;font-size:13px;margin-top:4px;opacity:.85}
.count{position:absolute;top:12px;right:12px}
.krow{display:flex;align-items:center;gap:12px;background:var(--paper);border:1px solid var(--line);border-radius:18px;padding:14px}
.bell{background:var(--paper);border:1px solid var(--line);border-radius:18px;overflow:hidden}
.brow{display:flex;gap:10px;padding:12px 14px;border-bottom:1px solid var(--line);font-size:14px;line-height:1.35}
.brow:last-child{border-bottom:0}.brow.unread{background:var(--primary-soft)}
.dot{width:8px;height:8px;border-radius:50%;background:var(--primary);margin-top:6px;flex:none}
.dot.read{background:transparent}
.time{font-size:12px;color:var(--ink-soft)}

